mapper.select:
select * from (
    select

    b.machine_name,
    tgf.mid_finish_qty,
    tgf.night_finish_qty,
    tgf.day_finish_qty,
    trt.recipe_type_name,
    ifnull(tgf.mid_finish_qty, 0) + ifnull(tgf.night_finish_qty, 0) + ifnull(tgf.day_finish_qty, 0) AS total_finish,
    CASE WHEN tgf.mid_finish_qty != 0 THEN TRUNCATE(a.mid_plan_qty/tgf.mid_finish_qty, 4) ELSE null END MID_FINISH_RATE,
    CASE WHEN tgf.night_finish_qty != 0 THEN TRUNCATE(a.night_plan_qty/tgf.night_finish_qty, 4) ELSE null END NIGHT_FINISH_RATE,
    CASE WHEN tgf.day_finish_qty != 0 THEN TRUNCATE(a.day_plan_qty/tgf.day_finish_qty, 4) ELSE null END DAY_FINISH_RATE
    from t_glue_schedule_result a
    left join t_mix_machine b on b.del_flag = 0 and a.machine_code = b.machine_code and a.mix_area = b.mix_area
    left join t_glue_finish tgf on a.order_no = tgf.order_no and tgf.del_flag = 0
    left join t_recipe_type trt on a.recipe_type = trt.recipe_type_code and trt.del_flag = 0
    where a.del_flag = '0'
    and a.schedule_date = #{scheduleDate}
    and a.mix_area = #{mixArea}
    and INSTR(a.glue, #{glue}) > 0
    and a.sap_code = #{sapCode}
    and a.machine_code = #{machineCode}
    and a.release_status = #{releaseStatus}
    and a.publish_success_count = #{publishSuccessCount}
    and a.newest_publish_time = #{newestPublishTime}
    and a.machine_code is not null
) t

    order by (case when instr(machine_name,'一次法') > 0 then concat('0',machine_code) when machine_name is null or machine_name = '' then '2' else concat('1',machine_code) end)/*一次法的机台排在前面*/, MID_PRODUCE_ORDER


    order by (case when instr(machine_name,'一次法') > 0 then concat('0',machine_code) when machine_name is null or machine_name = '' then '2' else concat('1',machine_code) end)/*一次法的机台排在前面*/, ${orderStr}

WITH temp_table AS (
SELECT #{rowNumber} row_numbers, #{data.scheduleDate} schedule_date, #{data.glue} glue, #{data.machineCode} machine_code FROM dual
) select #{importLogId} importLogId, t.row_numbers errorRow, #{errorDetail} errorDetail, #{createBy} createBy, now() createTime, m.schedule_date, m.glue, m.machine_code from t_glue_schedule_result m inner join temp_table t on m.schedule_date = t.schedule_date and m.glue = t.glue and m.machine_code = t.machine_code and m.del_flag ='0'

