cType=DATE} day_expect_start_time, #{glueScheduleResult.dayExpectFinishTime,jdbcType=DATE} day_expect_finish_time, #{glueScheduleResult.dayRemark,jdbcType= VARCHAR} day_remark, #{glueScheduleResult.releaseStatus,jdbcType= VARCHAR} release_status, #{glueScheduleResult.publishSuccessCount,jdbcType=DOUBLE} publish_success_count, #{glueScheduleResult.newestPublishTime,jdbcType=DATE} newest_publish_time, #{glueScheduleResult.dataSource,jdbcType= VARCHAR} data_source, #{glueScheduleResult.remark,jdbcType= VARCHAR} remark, #{glueScheduleResult.delFlag,jdbcType= VARCHAR} del_flag, #{glueScheduleResult.createBy,jdbcType= VARCHAR} create_by, #{glueScheduleResult.createTime,jdbcType=DATE} create_time, #{glueScheduleResult.updateBy,jdbcType= VARCHAR} update_by, #{glueScheduleResult.updateTime,jdbcType=DATE} update_time from dual
) x

