WITH temp_table AS (
SELECT #{data.id} id, #{data.scheduleDate} schedule_date, #{data.glue} glue, #{data.machineCode} machine_code, #{data.recipeType} recipe_type FROM dual
) select m.id, m.schedule_date, m.machine_code, m.glue from t_glue_schedule_result m inner join temp_table t on m.schedule_date = t.schedule_date and m.glue = t.glue and m.machine_code = t.machine_code and m.del_flag ='0' and t.recipe_type = m.recipe_type and m.id != t.id

select id, machine_name, mix_area, machine_code, remark,status, del_flag, create_by, create_time, update_by,
update_time from t_mix_machine
where del_flag = '0'
and machine_name = #{machineName}
and mix_area = #{mixArea}
and status = #{status}

